import { BUTTON_SIZES, BUTTON_VARIANTS, ICON_BUTTON_SIZES } from '../components/button-props'

const HEADER = `/*
 * Stencil button CSS for StButton and StIconButton: one rule per variant and size, each reading tokens.
 * GENERATED by \`pnpm stencil:tokens\` from stencil/components/button-props.ts. Do not edit by hand.
 */
`

const PADDING = { sm: '50 100', md: '100 150', lg: '100 200' } as const

const VARIANTS: Record<(typeof BUTTON_VARIANTS)[number], string[]> = {
  primary: [
    'background: var(--st-color-fill-primary); color: var(--st-color-text-on-primary);',
    '&:hover:not(:disabled) { background: color-mix(in oklab, var(--st-color-fill-primary) 85%, transparent); }'
  ],
  secondary: [
    'background: transparent; color: var(--st-color-text-primary); box-shadow: var(--st-ring-base);',
    '&:hover:not(:disabled) { background: var(--st-color-surface-hover); }'
  ],
  ghost: [
    'background: transparent; color: var(--st-color-text-secondary);',
    '&:hover:not(:disabled) { background: var(--st-color-surface-hover); color: var(--st-color-text-primary); }'
  ],
  link: [
    'background: transparent; color: var(--st-color-text-primary); padding: var(--st-space-25) 0; border-radius: var(--st-space-50);',
    '&:hover:not(:disabled) { text-decoration: underline; }'
  ],
  danger: [
    'background: transparent; color: var(--st-color-danger);',
    '&:hover:not(:disabled) { background: var(--st-color-surface-danger); }'
  ]
}

/** Renders the StButton and StIconButton rules as one stylesheet. */
export function renderButtonCss(): string {
  const rules: string[] = [
    '.st-button { display: inline-flex; flex: 0 0 auto; align-items: center; justify-content: center; gap: var(--st-space-75); box-sizing: border-box; border: 0; border-radius: var(--st-space-100); cursor: pointer; user-select: none; }',
    '.st-button:focus-visible { outline: var(--st-border-200) solid var(--st-color-focus); outline-offset: var(--st-space-25); }',
    '.st-button:disabled { opacity: 0.5; cursor: not-allowed; }'
  ]
  for (const size of BUTTON_SIZES) {
    rules.push(
      `.st-button[data-st-size='${size}'] { font: var(--st-type-label-${size}); padding: ${PADDING[
        size
      ]
        .split(' ')
        .map((stop) => `var(--st-space-${stop})`)
        .join(' ')}; }`
    )
  }
  for (const [variant, [base, hover]] of Object.entries(VARIANTS)) {
    rules.push(`.st-button[data-st-variant='${variant}'] { ${base} }`)
    rules.push(hover.replace('&', `.st-button[data-st-variant='${variant}']`))
  }
  for (const [size, spec] of Object.entries(ICON_BUTTON_SIZES)) {
    rules.push(
      `.st-icon-button[data-st-size='${size}'] { position: relative; width: var(--st-block-${spec.block}); height: var(--st-block-${spec.block}); padding: 0; }`
    )
  }
  return `${HEADER}\n${rules.join('\n')}\n`
}
